x=np.array([2.,-1.5,.5,3.,-1.]);y=np.array([3.4,-2.8,.2,5.1,-1.]);bs=np.linspace(.6,2.8,180);s=[np.sum((y-(y.mean()-q*x.mean()+q*x))**2) for q in bs];ax.plot(bs,s,color=ACCENT,lw=2);ax.axvline(25.1/14.7,color=BAD,ls='--');ax.set_xlabel('candidate slope (unitless)');ax.set_ylabel('SSE (percentage-points squared)');ax.set_title('OLS chooses the unique minimum squared error',loc='left')
